package cn.interview.service;

import cn.interview.client.ModelTask;
import cn.interview.common.ContentHash;
import cn.interview.exception.ApiException;
import cn.interview.exception.RecoveryException;
import cn.interview.mapper.TrainingStore;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.springframework.stereotype.Service;

import static cn.interview.common.Models.*;

@Service
public class JdService implements ModelTaskHandler {
    final TrainingStore db;final OperationService ops;final ModelTaskRunner runner;final InputPreparationService inputs;
    JdService(TrainingStore db,OperationService ops,ModelTaskRunner runner,InputPreparationService inputs){this.db=db;this.ops=ops;this.runner=runner;this.inputs=inputs;}
    public ObjectNode create(JsonNode body){return view(runner.run(ModelTask.JD_DIAGNOSTIC,"JD_DIAGNOSTIC","LOCAL_USER",body,()->{
        var manifest=inputs.load("JD_INPUT","LOCAL_USER",body);var row=db.object().put("familyId",id()).put("diagnosticVersion",1).put("status","RUNNING").put("mock",runner.llm.isMock());
        for(JsonNode event:manifest.path("modelInput").path("trainingEvents"))if(event.path("mock").asBoolean()!=row.path("mock").asBoolean())throw RecoveryException.conflict("V2_MODEL_MODE_CHANGED","训练证据与当前模型模式不同");
        if(body.hasNonNull("replaceOf")){var previous=db.get("v2_jd_diagnostics",required(body,"replaceOf",100));row.put("familyId",previous.path("familyId").asText()).put("replaceOf",previous.path("id").asText());row.put("diagnosticVersion",db.nextDiagnosticVersion(row.path("familyId").asText()));}
        row.set("manifest",manifest.deepCopy());db.insert("v2_jd_diagnostics",row);return new ModelTaskRunner.Work("v2_jd_diagnostics",row,(ObjectNode)manifest.path("modelInput").deepCopy());
    }));}
    ObjectNode view(ObjectNode row){var out=row.deepCopy();out.put("sourcesChanged",inputs.changed(row.path("manifest")));if(out.has("protocol"))out.set("protocol",runner.llm.publicProtocol(out.path("protocol")));out.remove("result");for(JsonNode r:out.path("requirements"))((ObjectNode)r).put("currentTrainingStatus",currentTrainingStatus(r));return out;}
    String currentTrainingStatus(JsonNode requirement){
        boolean support=false,gap=false;for(JsonNode binding:requirement.path("trainingBindings")){
            try{var observation=inputs.trainingSource(binding.path("eventId").asText()).path("observation");JsonNode match=null;for(JsonNode finding:observation.path("findings"))if(finding.path("id").asText().equals(binding.path("findingId").asText()))match=finding;
                if(match==null)return "DISPUTED";support|=match.path("status").asText().equals("SUPPORTED");gap|=match.path("status").asText().equals("GAP");
            }catch(ApiException e){return "DISPUTED";}
        }return gap?"GAP":support?"SUPPORTED":"UNVERIFIED";
    }
    public ObjectNode list(String cursor,int limit){var page=db.page("v2_jd_diagnostics",cursor,limit,null);for(JsonNode row:page.path("items")){var r=(ObjectNode)row;r.put("sourcesChanged",inputs.changed(r.path("manifest")));r.remove(List.of("manifest","requirements","result","protocol"));}return page;}
    public ObjectNode confirm(String id,JsonNode body){return view(ops.write("JD_CONFIRM",id,body,()->{var d=db.get("v2_jd_diagnostics",id);db.expect(d,body);if(!d.path("status").asText().equals("READY"))throw RecoveryException.conflict("V2_INVALID_STATE","请选择已生成但尚未确认的诊断；已确认版本保留");inputs.check(d.path("manifest"));var selected=selected(d,body.path("requirementIds"),false);for(JsonNode r:d.path("requirements")){var row=(ObjectNode)r;row.put("confirmed",selected.contains(r.path("id").asText()));if(row.path("confirmed").asBoolean()){String importance=body.path("importanceUpdates").path(row.path("id").asText()).asText(row.path("importance").asText());choice(importance,"REQUIRED","PREFERRED","UNSPECIFIED");row.put("importance",importance).put("priorityOrigin","USER_CONFIRMED").put("confirmedAt",now());}}
        d.put("status","CONFIRMED");return db.save("v2_jd_diagnostics",d,d.path("revision").asInt());}));}
    Set<String> selected(JsonNode d,JsonNode ids,boolean confirmed){if(!ids.isArray()||ids.isEmpty()||ids.size()>12)throw RecoveryException.invalid("请选择1～12条要求");var valid=new HashSet<String>();for(JsonNode r:d.path("requirements"))if(!confirmed||r.path("confirmed").asBoolean())valid.add(r.path("id").asText());var result=new HashSet<String>();for(JsonNode id:ids)if(!valid.contains(id.asText())||!result.add(id.asText()))throw RecoveryException.invalid("要求不存在、未确认或重复");return result;}
    ObjectNode requirement(JsonNode d,String id){for(JsonNode r:d.path("requirements"))if(r.path("id").asText().equals(id)&&r.path("confirmed").asBoolean())return (ObjectNode)r;throw RecoveryException.invalid("要求不属于已确认范围");}
    ArrayNode actions(JsonNode diagnostic,JsonNode raw){if(!raw.isArray()||raw.isEmpty()||raw.size()>5)throw RecoveryException.invalid("请选择1～5个具体行动");var list=db.array();for(JsonNode input:raw){String rid=required(input,"requirementId",100);var r=requirement(diagnostic,rid);String type=choice(required(input,"type",30),"MATERIAL_UPDATE","VERIFY_REQUIREMENT","RETRY_QUESTION");var row=list.addObject().put("id",id()).put("requirementId",rid).put("type",type).put("purpose",required(input,"purpose",1000)).put("completionCondition",required(input,"completionCondition",1000)).put("priorityReason",r.path("priorityReason").asText()).put("priorityOrigin","USER_CONFIRMED").put("status","TODO").put("entryPath",type.equals("MATERIAL_UPDATE")?"/materials":"/configure/quick");row.put("priority",r.path("importance").asText().equals("REQUIRED")?(r.path("trainingStatus").asText().equals("GAP")?1:r.path("trainingStatus").asText().equals("UNVERIFIED")?2:3):3);row.put("sourceDiagnosticId",diagnostic.path("id").asText());row.set("requirementSnapshot",r.deepCopy());}var sorted=new ArrayList<JsonNode>();list.forEach(sorted::add);sorted.sort(Comparator.comparingInt(a->a.path("priority").asInt()));var out=db.array();sorted.forEach(out::add);return out;}
    public ObjectNode sprint(JsonNode body){return ops.write("SPRINT_CREATE","LOCAL_USER",body,()->{var d=db.get("v2_jd_diagnostics",required(body,"confirmedDiagnosticId",100));if(!d.path("status").asText().equals("CONFIRMED"))throw RecoveryException.conflict("V2_SOURCE_NOT_READY","先逐条确认诊断要求，再创建短清单");inputs.check(d.path("manifest"));var s=db.object().put("diagnosticId",d.path("id").asText()).put("status","ACTIVE").put("windowDays",7).put("windowNotice","7天仅作参考，不代表承诺掌握或录用概率");s.set("actions",actions(d,body.path("actions")));return db.insert("v2_sprints",s);});}
    public ObjectNode sprintView(String id){var row=db.get("v2_sprints",id);var d=db.get("v2_jd_diagnostics",row.path("diagnosticId").asText());row.put("sourcesChanged",inputs.changed(d.path("manifest")));for(JsonNode a:row.path("actions"))((ObjectNode)a).put("currentTrainingStatus",currentTrainingStatus(a.path("requirementSnapshot")));return row;}
    public ObjectNode diff(String id,String diagnosticId){var s=db.get("v2_sprints",id);var old=db.get("v2_jd_diagnostics",s.path("diagnosticId").asText());var next=db.get("v2_jd_diagnostics",diagnosticId);if(!next.path("status").asText().equals("CONFIRMED")||!next.path("familyId").asText().equals(old.path("familyId").asText())||next.path("diagnosticVersion").asInt()<=old.path("diagnosticVersion").asInt())throw RecoveryException.invalid("请选择同一诊断族中较新的已确认版本");inputs.check(next.path("manifest"));var out=db.object().put("sprintId",id).put("oldDiagnosticId",old.path("id").asText()).put("diagnosticId",diagnosticId).put("revision",s.path("revision").asInt());var kept=out.putArray("kept");var obsolete=out.putArray("obsolete");var completed=out.putArray("completed");for(JsonNode action:s.path("actions")){if(action.path("status").asText().equals("DONE"))completed.add(action.path("id").asText());try{requirement(next,action.path("requirementId").asText());kept.add(action.path("id").asText());}catch(ApiException e){obsolete.add(action.path("id").asText());}}out.put("diffHash",db.hash(out));return out;}
    public ObjectNode action(String id,JsonNode body){return ops.write("SPRINT_ACTION",id,body,()->{var s=db.get("v2_sprints",id);db.expect(s,body);if(!s.path("status").asText().equals("ACTIVE"))throw RecoveryException.conflict("V2_INVALID_STATE","清单已归档");String action=required(body,"action",40);var d=db.get("v2_jd_diagnostics",s.path("diagnosticId").asText());
        if(action.equals("APPLY_DIAGNOSTIC")){var diff=diff(id,required(body,"diagnosticId",100));if(!body.path("confirmDifferences").asBoolean()||!required(body,"diffHash",100).equals(diff.path("diffHash").asText()))throw RecoveryException.conflict("V2_SOURCE_CHANGED","请先查看并确认新增、保留、失效及完成记录差异");var nextDiagnostic=db.get("v2_jd_diagnostics",body.path("diagnosticId").asText());for(JsonNode row:s.path("actions")){if(ReviewService.contains(diff.path("obsolete"),row.path("id").asText()))((ObjectNode)row).put("obsolete",true);else if(ReviewService.contains(diff.path("kept"),row.path("id").asText())&&!row.path("status").asText().equals("DONE")){var actionRow=(ObjectNode)row;if(!actionRow.has("originalSourceDiagnosticId")){actionRow.put("originalSourceDiagnosticId",actionRow.path("sourceDiagnosticId").asText());actionRow.set("originalRequirementSnapshot",actionRow.path("requirementSnapshot").deepCopy());}actionRow.put("sourceDiagnosticId",nextDiagnostic.path("id").asText());actionRow.set("requirementSnapshot",requirement(nextDiagnostic,actionRow.path("requirementId").asText()).deepCopy());}}s.put("diagnosticId",body.path("diagnosticId").asText());if(body.has("newActions")){var nd=db.get("v2_jd_diagnostics",body.path("diagnosticId").asText());for(JsonNode row:actions(nd,body.path("newActions")))s.withArray("actions").add(row);}int active=0;for(JsonNode row:s.path("actions"))if(!row.path("obsolete").asBoolean()&&Set.of("TODO","IN_PROGRESS").contains(row.path("status").asText()))active++;if(active>5)throw RecoveryException.invalid("新版本活动项仍不可超过5个");s.set("lastDiagnosticChange",diff);if(s.path("actions").size()>100)throw new RecoveryException(413,"V2_SPRINT_LIMIT","此清单已保存100个行动，请依据新诊断另建清单；所有旧行动和操作历史保留。","CREATE_SPRINT");}
        else if(action.equals("REORDER")){if(!body.path("actionIds").isArray()||body.path("actionIds").size()!=s.path("actions").size())throw RecoveryException.invalid("排序需包含所有行动，不能丢弃历史");var ordered=db.array();var seen=new HashSet<String>();for(JsonNode aid:body.path("actionIds")){if(!seen.add(aid.asText()))throw RecoveryException.invalid("排序 ID 重复");var row=findAction(s,aid.asText());if(row.path("priority").asInt()!=s.path("actions").get(ordered.size()).path("priority").asInt())throw RecoveryException.invalid("只能在相同优先级内调整行动顺序");ordered.add(row);}s.set("actions",ordered);}
        else if(action.equals("ARCHIVE"))s.put("status","ARCHIVED");
        else{var row=findAction(s,required(body,"actionId",100));String state=row.path("status").asText();switch(action){
            case "START"->{if(!state.equals("TODO")||row.path("obsolete").asBoolean())throw RecoveryException.conflict("V2_INVALID_STATE","仅当前待办可开始");row.put("status","IN_PROGRESS");}
            case "SKIP"->{if(state.equals("DONE"))throw RecoveryException.conflict("V2_INVALID_STATE","已完成记录需先重开");row.put("status","SKIPPED").put("skipReason",required(body,"reason",1000));}
            case "REOPEN"->{if(!Set.of("DONE","SKIPPED").contains(state)||row.path("obsolete").asBoolean())throw RecoveryException.conflict("V2_INVALID_STATE","当前行动不能重开");int active=0;for(JsonNode a:s.path("actions"))if(!a.path("obsolete").asBoolean()&&Set.of("TODO","IN_PROGRESS").contains(a.path("status").asText()))active++;if(active>=5)throw RecoveryException.invalid("活动项已达5个，请先完成或跳过其他项");inputs.check(d.path("manifest"));var currentRequirement=requirement(d,row.path("requirementId").asText());if(!row.path("sourceDiagnosticId").asText().equals(d.path("id").asText())){if(!row.has("originalSourceDiagnosticId")){row.put("originalSourceDiagnosticId",row.path("sourceDiagnosticId").asText());row.set("originalRequirementSnapshot",row.path("requirementSnapshot").deepCopy());}row.put("sourceDiagnosticId",d.path("id").asText());row.set("requirementSnapshot",currentRequirement.deepCopy());}row.put("status","TODO");}
            case "COMPLETE"->{if(!Set.of("TODO","IN_PROGRESS").contains(state)||row.path("obsolete").asBoolean())throw RecoveryException.conflict("V2_INVALID_STATE","当前行动不能完成");if(!row.path("type").asText().equals("MATERIAL_UPDATE"))inputs.check(d.path("manifest"));var sourceDiagnostic=db.get("v2_jd_diagnostics",row.path("sourceDiagnosticId").asText(s.path("diagnosticId").asText()));row.set("completionEvidence",completion(sourceDiagnostic,row,body));row.put("status","DONE").put("completionOrigin","USER_CONFIRMED");}
            default->throw RecoveryException.invalid("不支持的清单动作");}var event=db.object().put("action",action).put("at",now());if(row.has("completionEvidence"))event.set("evidence",row.path("completionEvidence").deepCopy());row.set("lastChange",event);}
        return db.save("v2_sprints",s,s.path("revision").asInt());});}
    ObjectNode findAction(JsonNode s,String id){for(JsonNode row:s.path("actions"))if(row.path("id").asText().equals(id))return (ObjectNode)row;throw RecoveryException.invalid("行动不存在");}
    ObjectNode completion(JsonNode d,JsonNode action,JsonNode body){if(!body.path("coverageConfirmed").asBoolean())throw RecoveryException.invalid("请明确确认本次资料或训练覆盖所选要求");var out=db.object().put("confirmedAt",now()).put("requirementId",action.path("requirementId").asText());
        if(action.path("type").asText().equals("MATERIAL_UPDATE")){String mid=required(body,"materialId",100);var current=db.json().valueToTree(db.database().material(mid));String hash=db.hash(current);if(!required(body,"materialHash",100).equals(hash))throw RecoveryException.conflict("V2_SOURCE_CHANGED","资料已变化，请重新确认");for(JsonNode dep:d.path("manifest").path("dependencies"))if(dep.path("kind").asText().equals("MATERIAL")&&dep.path("id").asText().equals(mid)&&dep.path("hash").asText().equals(hash))throw RecoveryException.invalid("该资料仍是原版本，请先补充或修订再确认");out.put("materialId",mid).put("materialHash",hash);out.set("materialSnapshot",completionMaterial(mid));return out;}
        var link=db.get("v2_training_links",required(body,"trainingLinkId",100));if(!link.path("sourceKind").asText().equals("JD")||!link.path("sourceId").asText().equals(d.path("id").asText())||!ReviewService.contains(link.path("requirementIds"),action.path("requirementId").asText()))throw RecoveryException.invalid("练习来源没有覆盖此要求");var session=db.database().session(link.path("sessionId").asText());if(!session.path("status").asText().equals("COMPLETED")||!session.path("reportStatus").asText().equals("READY"))throw RecoveryException.conflict("V2_EVIDENCE_INSUFFICIENT","请先完成专项练习及报告");var report=db.database().report(session.path("id").asText());JsonNode question=null;for(JsonNode q:report.path("questions"))if(q.path("questionIndex").asInt()==body.path("evidenceQuestionIndex").asInt(-1))question=q;if(question==null)throw RecoveryException.invalid("请选择实际覆盖此要求的一题");String kind=choice(required(body,"reportKind",30),"correct","incorrect","missing","uncertain"),text=required(body,"reportText",4000);if(!ReviewService.contains(question.path(kind),text))throw RecoveryException.invalid("依据不属于所选报告题目");out.put("trainingLinkId",link.path("id").asText()).put("reportHash",db.hash(report)).put("evidenceQuestionIndex",body.path("evidenceQuestionIndex").asInt()).put("reportKind",kind).put("reportText",text).put("reason",required(body,"reason",1000));return out;
    }
    ObjectNode completionMaterial(String id){var m=db.database().material(id);var out=db.object().put("id",m.id()).put("name",m.name()).put("hash",db.hash(db.json().valueToTree(m))).put("kind",m.kind());if(!Set.of("RESUME","PROJECT").contains(m.kind()))throw RecoveryException.invalid("请选择简历或项目资料");var snapshots=out.putArray("snapshots");var size=new int[]{0};inputs.addMaterial(snapshots,db.object(),"material:"+id,m.content(),false,id,null,size);for(var doc:m.documents())inputs.addMaterial(snapshots,db.object(),"document:"+doc.id(),doc.text(),doc.truncated(),id,doc.id(),size);if(snapshots.isEmpty())throw RecoveryException.invalid("资料为空，请先补充具体事实");return out;}
    public boolean supports(ModelTask task){return task==ModelTask.JD_DIAGNOSTIC;}
    public void running(ObjectNode row,ObjectNode op){row.put("status","RUNNING");}
    public void failed(ObjectNode row,ObjectNode op,boolean interrupted){row.put("status",interrupted?"INTERRUPTED":"FAILED");}
    public void completed(ObjectNode row,ObjectNode result,ObjectNode op){row.put("status","READY");row.set("protocol",op.path("protocol").deepCopy());var requirements=((ArrayNode)result.path("requirements")).deepCopy();for(JsonNode r:requirements)((ObjectNode)r).put("id",ContentHash.sha(row.path("familyId").asText()+"|"+r.path("jdEvidence").path("quote").asText()+"|"+row.path("manifest").path("modelInput").path("jdSourceIdentity").asText())).put("confirmed",false).put("priorityOrigin","MODEL_SUGGESTION");row.set("requirements",requirements);row.put("coverageNotice",result.path("coverageNotice").asText());}

    public ObjectNode prepare(JsonNode body) {return inputs.prepareJd(body);}

    public ObjectNode get(String id) {return view(db.get("v2_jd_diagnostics",id));}

    public ObjectNode sprints(String cursor,int limit) {var page=db.page("v2_sprints",cursor,limit,null);page.path("items").forEach(row->((com.fasterxml.jackson.databind.node.ObjectNode)row).remove(java.util.List.of("actions","diagnosticHistory")));return page;}

    public ObjectNode history(String id,String cursor,int limit) {return ops.history("v2_sprints",id,cursor,limit);}

    public ObjectNode historyDetail(String id,String operationId) {return ops.historyDetail("v2_sprints",id,operationId);}

    public ObjectNode completionMaterial(String id,String materialId) {db.get("v2_jd_diagnostics",id);return completionMaterial(materialId);}

    public ObjectNode observations(String cursor,int limit) {
        var page=db.page("v2_skill_events",cursor,limit,null);var items=db.array();for(JsonNode event:page.path("items"))try{items.add(inputs.trainingSource(event.path("id").asText()).path("observation"));}catch(ApiException ignored){/* 不接受的自评、归类与争议事件不作为选材。 */}page.set("items",items);return page;
    }

    public ObjectNode availableMaterials(String cursor,int limit) {db.enabled();return db.database().availableMaterials(cursor,limit);}

}
